import { BQ79600PWRQ1 } from "./lib/imports/BQ79600PWRQ1"
import { HMU1228NLT_CND } from "./lib/imports/HMU1228NLT_CND"
import { USBLC6_2SC6 } from "./lib/imports/USBLC6_2SC6"

export const CommunicationBridge = () => (
  <board>
    {/* ICs */}
    <BQ79600PWRQ1 name="U1" />
    <HMU1228NLT_CND name="T1" /> {/* COML Transformer */}
    <HMU1228NLT_CND name="T2" /> {/* COMH Transformer */}
    <USBLC6_2SC6 name="D_ESD1" /> {/* ESD Protection for SCLK, nCS */}
    <USBLC6_2SC6 name="D_ESD2" /> {/* ESD Protection for MOSI, MISO */}

    {/* Capacitors */}
    <capacitor name="C1" capacitance="100nF" voltage="50V" footprint="0603" /> {/* BAT Decoupling */}
    <capacitor name="C2" capacitance="470nF" voltage="10V" footprint="0603" /> {/* CVDD Decoupling */}
    <capacitor name="C3" capacitance="470nF" voltage="10V" footprint="0603" /> {/* DVDD Decoupling */}
    <capacitor name="C4" capacitance="100nF" voltage="10V" footprint="0603" /> {/* VIO Decoupling */}
    <capacitor name="C5" capacitance="10nF" voltage="50V" footprint="0603" />  {/* COML Bias Filter */}
    <capacitor name="C6" capacitance="10nF" voltage="50V" footprint="0603" />  {/* COMH Bias Filter */}
    <capacitor name="C9" capacitance="100pF" voltage="100V" footprint="0603" /> {/* COMLP ISO Filter */}
    <capacitor name="C10" capacitance="100pF" voltage="100V" footprint="0603" /> {/* COMLN ISO Filter */}
    <capacitor name="C11" capacitance="100pF" voltage="100V" footprint="0603" /> {/* COMHP ISO Filter */}
    <capacitor name="C12" capacitance="100pF" voltage="100V" footprint="0603" /> {/* COMHN ISO Filter */}

    {/* Resistors */}
    <resistor name="R1" resistance="10" footprint="0603" />      {/* INH Series protection */}
    <resistor name="R5" resistance="200" footprint="0603" />     {/* CVDD LED Resistor */}
    <resistor name="R11" resistance="200" footprint="0603" />    {/* NFAULT LED Resistor */}
    <resistor name="R23" resistance="51" footprint="0603" />     {/* COMHP Termination 1 */}
    <resistor name="R33" resistance="51" footprint="0603" />     {/* COMHN Termination 2 */}
    <resistor name="R24" resistance="51" footprint="0603" />     {/* COMLP Termination 1 */}
    <resistor name="R34" resistance="51" footprint="0603" />     {/* COMLN Termination 2 */}
    <resistor name="R27" resistance="499" footprint="0603" />    {/* COMH Bias 1 */}
    <resistor name="R28" resistance="499" footprint="0603" />    {/* COMH Bias 2 */}
    <resistor name="R29" resistance="499" footprint="0603" />    {/* COML Bias 1 */}
    <resistor name="R30" resistance="499" footprint="0603" />    {/* COML Bias 2 */}
    <resistor name="R_PU1" resistance="10k" footprint="0603" />  {/* NFAULT Pull-up */}
    <resistor name="R_STRAP" resistance="10k" footprint="0603" /> {/* Mode Selection Pull-up */}

    {/* LEDs */}
    <led name="D2" color="green" footprint="0603" /> {/* Power LED */}
    <led name="D3" color="red" footprint="0603" />   {/* Fault LED */}

    {/* Net Connections */}

    {/* Power and Ground */}
    <net name="GND" pins={["U1.GND", "C1.pin2", "C2.pin2", "C3.pin2", "C4.pin2", "C5.pin2", "C6.pin2", "D_ESD1.pin2", "D_ESD2.pin2", "D2.cathode", "R27.pin2", "R28.pin2", "R29.pin2", "R30.pin2"]} />
    <net name="BAT" pins={["U1.BAT", "C1.pin1"]} />
    <net name="VIO" pins={["U1.VIO", "C4.pin1", "R_PU1.pin2", "R_STRAP.pin2", "D_ESD1.pin5", "D_ESD2.pin5", "R11.pin1"]} />
    <net name="CVDD" pins={["U1.CVDD", "C2.pin1", "R5.pin1"]} />
    <net name="DVDD" pins={["U1.DVDD", "C3.pin1"]} />

    {/* LED Connections */}
    <net name="CVDD_LED_NET" pins={["R5.pin2", "D2.anode"]} />
    <net name="NFAULT_LED_NET" pins={["R11.pin2", "D3.anode"]} />

    {/* Host Interface Signals */}
    <net name="NFAULT" pins={["U1.NFAULT", "R_PU1.pin1", "D3.cathode"]} />
    <net name="SCLK" pins={["U1.SCLK", "D_ESD1.pin1"]} />
    <net name="nCS" pins={["U1.nCS", "D_ESD1.pin3"]} />
    <net name="MOSI" pins={["U1.pin4", "D_ESD2.pin1"]} />
    <net name="MISO" pins={["U1.pin5", "D_ESD2.pin3"]} />
    <net name="nUART_SPI" pins={["U1.pin8", "R_STRAP.pin1"]} />
    <net name="INH" pins={["U1.INH", "R1.pin1"]} />
    <net name="INH_OUT" pins={["R1.pin2"]} />

    {/* COMH (Daisy Chain High) */}
    <net name="COMHP" pins={["U1.COMHP", "R23.pin1", "T2.pin1"]} />
    <net name="COMHN" pins={["U1.COMHN", "R33.pin1", "T2.pin3"]} />
    <net name="COMH_CT" pins={["R23.pin2", "R33.pin2", "T2.pin2", "C6.pin1", "R27.pin1", "R28.pin1"]} />

    <net name="COMHP_ISO" pins={["T2.pin6", "C11.pin1"]} />
    <net name="COMHN_ISO" pins={["T2.pin4", "C12.pin1"]} />
    <net name="COMH_CT_ISO" pins={["T2.pin5", "C11.pin2", "C12.pin2"]} />

    {/* COML (Daisy Chain Low) */}
    <net name="COMLP" pins={["U1.COMLP", "R24.pin1", "T1.pin1"]} />
    <net name="COMLN" pins={["U1.COMLN", "R34.pin1", "T1.pin3"]} />
    <net name="COML_CT" pins={["R24.pin2", "R34.pin2", "T1.pin2", "C5.pin1", "R29.pin1", "R30.pin1"]} />

    <net name="COMLP_ISO" pins={["T1.pin6", "C9.pin1"]} />
    <net name="COMLN_ISO" pins={["T1.pin4", "C10.pin1"]} />
    <net name="COML_CT_ISO" pins={["T1.pin5", "C9.pin2", "C10.pin2"]} />

    {/* External Ports */}
    <port name="P2_1" net="BAT" />
    <port name="P2_2" net="VIO" />
    <port name="P2_3" net="GND" />
    <port name="P2_4" net="SCLK" />
    <port name="P2_5" net="nCS" />
    <port name="P2_6" net="MOSI" />
    <port name="P2_7" net="MISO" />
    <port name="P2_8" net="nUART_SPI" />
    <port name="P2_9" net="NFAULT" />
    <port name="P2_10" net="INH_OUT" />
    <port name="P2_11" net="DVDD" />

    <port name="P1_1_P" net="COMLP_ISO" />
    <port name="P1_1_N" net="COMLN_ISO" />
    <port name="P1_2_P" net="COMHP_ISO" />
    <port name="P1_2_N" net="COMHN_ISO" />
    <port name="P1_3" net="CVDD" />

  </board>
)

